nested:
{
	return (TPath({ pack : [], name : "Array", params : [TPType(TPath({ pack : [], name : "Map", params : [TPType(TPath({ pack : [], name : "String", params : [] })), TPType(TPath({ pack : [], name : "Int", params : [] }))] }))] }) : haxe.macro.Expr.ComplexType);
}

subType:
{
	return (TPath({ pack : ["haxe", "macro"], name : "Expr", params : [], sub : "ComplexType" }) : haxe.macro.Expr.ComplexType);
}

replaced:
{
	return (TPath({ pack : tp.pack, name : tp.name, sub : tp.sub, params : [TPType(TPath({ pack : [], name : "Bool", params : [] }))] }) : haxe.macro.Expr.ComplexType);
}

functions:
{
	return [(TFunction([TPath({ pack : [], name : "Int", params : [] })], TPath({ pack : [], name : "String", params : [] })) : haxe.macro.Expr.ComplexType), (TFunction([TPath({ pack : [], name : "Int", params : [] }), TOptional(TPath({ pack : [], name : "String", params : [] }))], TPath({ pack : [], name : "Void", params : [] })) : haxe.macro.Expr.ComplexType), (TFunction([TNamed("a", TPath({ pack : [], name : "Int", params : [] })), TNamed("b", TPath({ pack : [], name : "Float", params : [] }))], TPath({ pack : [], name : "Bool", params : [] })) : haxe.macro.Expr.ComplexType), (TFunction([TParent(TOptional(TPath({ pack : [], name : "Int", params : [] })))], TPath({ pack : [], name : "Void", params : [] })) : haxe.macro.Expr.ComplexType)];
}

others:
{
	return [(TParent(TPath({ pack : [], name : "Int", params : [] })) : haxe.macro.Expr.ComplexType), (TIntersection([TPath({ pack : [], name : "Main", params : [] }), TPath({ pack : [], name : "Printer", params : [] })]) : haxe.macro.Expr.ComplexType)];
}
